-- 030_grammar_reference_expansion.sql
--
-- Gramer Rehberi genisletmesi + sinav soru havuzu buyutmesi (kullanicinin
-- "sinav soru sayisi az, bunu artir" talebine ve daha once anlasilan Gramer
-- PDF plani -- Cambridge "English Grammar in Use" 5. baski, Raymond
-- Murphy -- karsiligi).
--
-- ICERIK KAYNAGI VE TELIF NOTU: Bu migration'daki grammar_topics kayitlarinin
-- SADECE unite/konu basliklari (orn. "Going to ve Will Farki", "Third
-- Conditional") kitaptaki standart dilbilgisi terminolojisinden esinlenerek
-- adlandirilmistir -- bunlar telife konu olmayan genel gramer kavramlaridir.
-- Kural aciklamalari (rule_content_md), ornek cumleler (example_sentences),
-- sik hatalar (common_mistakes) ve tum exam_questions sorulari %100 ozgun
-- olarak yeniden yazilmistir. Kitaptan hicbir cumle, ornek veya alistirma
-- birebir kopyalanmamistir.
--
-- Icerik: 5 yeni grammar_categories (future, ing-to-infinitive,
-- pronouns-determiners, adjectives-adverbs, prepositions), 24 yeni
-- grammar_topics (bir kismi yeni kategorilerde, bir kismi mevcut 9 kategoriye
-- ek olarak), 48 yeni exam_questions -- bunlar mevcut 45 sorunun aksine
-- KELIME/sozcuk degil, DILBILGISI YAPISI (tenses, conditionals, passive,
-- relative clauses, prepositions vb.) test eder ve topic_tag'leri yukaridaki
-- yeni grammar_topics.slug degerleriyle birebir eslesir (029'daki notta
-- belirtilen bosluk boylece kapatilmistir).
--
-- Not: Bu, Murphy kitabinin 145 unitelik tam icerigi degil, ilk 24 unitelik
-- bir genisleme dalgasidir; kalan konular backlog'da.
--
-- Bu SQL, Supabase MCP execute_sql/apply_migration araciyla proje
-- mrxeuxscyztpiuagsumh uzerinde 3 parcada (categories, topics, questions)
-- zaten uygulanmistir; bu dosya repo gecmisi icin ayniyla tekrar eder.

-- new grammar_categories
INSERT INTO grammar_categories (id, slug, name_tr, name_en, sort_order) VALUES ('61d02907-0253-40a4-b4d1-0c74272921d9', 'future', 'Gelecek Zaman', 'Future', 10);
